];
return [{ json: { tz, today, days: lookahead, calendars: urls.length, events, errors, failed, cached, warnings: S.warnings.concat(notes), timing: { fetchMs: t2 - t1, parseMs: Date.now() - t2, totalMs: Date.now() - t0 } } }];

// n8n Code node. Scans the inbox for new/changed files, extracts their text, asks the AI for tasks
// and appends them to tasks.csv (as "待确认", or "进行中" when BRIEF_AUTO_CONFIRM is on and the date is explicit).
// Dates are validated and resolved by code, never trusted blindly.
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
// Shared by several Code nodes (inlined by the build script via the include marker).
const TASK_COLUMNS = ['状态', '分类', '任务', '截止日', '预估耗时', '来源', '添加时间', '备注'];
const REQUIRED_COLUMNS = ['状态', '任务', '截止日'];
const TEXT_COLUMNS = ['分类', '任务', '备注', '来源'];

// What the "状态" column means. Anything unknown is treated as active-but-suspicious by the callers, never silently hidden.
function statusKind(s) {
  const v = String(s ?? '').trim().toLowerCase();
  if (v === '进行中' || v === 'active' || v === 'doing') return 'active';
  if (v === '待确认' || v === 'pending') return 'pending';
  if (['完成', '已完成', 'done', 'completed', 'finished'].includes(v)) return 'done';
  if (['忽略', '已忽略', 'ignore', 'ignored', '取消', '已取消', 'cancelled', 'canceled'].includes(v)) return 'ignored';
  return v === '' ? 'pending' : 'unknown';
}

function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', q = false;
  const s = String(text).replace(/^\uFEFF/, '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === '"' && s[i + 1] === '"') { cell += '"'; i++; }
      else if (c === '"') q = false;
      else cell += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some((x) => x !== '')) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((x) => x !== '')) rows.push(row);
  return rows;
}

// Accepts what people and spreadsheets write: 2026-10-02, 2026/10/2, 2026.10.2 (optionally followed by a time).
// Returns YYYY-MM-DD, or '' when it is not a real calendar date.
function normalizeDate(s) {
  const str = String(s ?? '').trim();
  let m = str.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T].*)?$/);
  if (!m) {
    // Excel saves 25/12/2026 (D/M, Hong Kong, UK) or 12/25/2026 (M/D, US). Only the unambiguous ones are accepted:
    // 3/4/2026 could be either, and a wrong guess is worse than the "unrecognised date" note the brief gives.
    const dm = str.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})(?:[ T].*)?$/);
    if (!dm) return '';
    const a = Number(dm[1]), b = Number(dm[2]);
    if (a > 12 && b <= 12) m = [str, dm[3], dm[2], dm[1]]; else if (b > 12 && a <= 12) m = [str, dm[3], dm[1], dm[2]]; else return '';
  }
  const iso = `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  const d = new Date(`${iso}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== iso ? '' : iso;
}

// Spreadsheet formula injection: text starting with = + - @ gets an apostrophe on write, removed again on read.
const neutralize = (v) => (/^[=+\-@\t\r]/.test(v) ? `'${v}` : v);
const restore = (v) => (/^'[=+\-@\t\r]/.test(v) ? v.slice(1) : v);

// Throws when the header is not recognisable: callers must then leave the file alone instead of rewriting it.
function readTasks(file, fs) {
  const withColumns = (arr, cols) => { arr.columns = cols; return arr; }; // the column list travels with the rows, so a header-only file keeps its custom columns
  if (!fs.existsSync(file)) return withColumns([], [...TASK_COLUMNS]);
  const rows = parseCsv(fs.readFileSync(file, 'utf8'));
  if (!rows.length) return withColumns([], [...TASK_COLUMNS]);
  const head = rows[0].map((h) => h.trim());
  const missing = REQUIRED_COLUMNS.filter((c) => !head.includes(c));
  if (missing.length) throw new Error(`任务表表头无法识别（缺少列：${missing.join('、')}），程序不会改动这个文件。请恢复表头：${TASK_COLUMNS.join(',')}`);
  // Columns the user added themselves (for example "优先级") are carried along and written back untouched.
  const extra = head.filter((h, i) => h && !TASK_COLUMNS.includes(h) && head.indexOf(h) === i);
  return withColumns(rows.slice(1).map((r) => Object.fromEntries([...TASK_COLUMNS, ...extra].map((c) => {
    const v = (r[head.indexOf(c)] ?? '').trim();
    return [c, TEXT_COLUMNS.includes(c) ? restore(v) : v];
  }))), [...TASK_COLUMNS, ...extra]);
}

// options.backup (default true): keep the previous file as file.bak. A run that writes several times passes false after
// the first write, so the backup is always the file exactly as the user left it before the run.
function writeTasks(file, tasks, fs, options = {}) {
  const esc = (v) => (/[",\n\r]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
  const cell = (t, c) => esc(TEXT_COLUMNS.includes(c) ? neutralize(String(t[c] ?? '')) : String(t[c] ?? ''));
  const extra = [];
  for (const c of tasks.columns || []) if (!TASK_COLUMNS.includes(c) && !extra.includes(c)) extra.push(c);
  for (const t of tasks) for (const k of Object.keys(t)) if (!TASK_COLUMNS.includes(k) && !extra.includes(k)) extra.push(k);
  const cols = [...TASK_COLUMNS, ...extra];
  const lines = [cols.map(esc).join(','), ...tasks.map((t) => cols.map((c) => cell(t, c)).join(','))];
  if (options.backup !== false && fs.existsSync(file)) fs.copyFileSync(file, `${file}.bak`);
  const tmp = `${file}.tmp`;
  fs.writeFileSync(tmp, `\uFEFF${lines.join('\r\n')}\r\n`, 'utf8'); // BOM so Excel shows Chinese correctly
  fs.renameSync(tmp, file);
}

// Validated settings, shared by the Code nodes (inlined by the build script). Needs csv.js (normalizeDate) before it.
// A wrong value never stops the brief: it falls back to a safe default and the fallback is listed in `warnings`,
// which the brief prints, so a typo costs you a warning line instead of the whole morning.
function loadSettings($env) {
  const warnings = [];
  // soft: values below it are accepted but flagged (a budget of "5" is almost certainly meant as seconds, not milliseconds)
  const num = (name, def, min, max, soft = min) => {
    const raw = $env[name];
    if (raw === undefined || raw === '') return def;
    const n = Number(raw);
    if (!Number.isFinite(n) || n < min || n > max) { warnings.push(`${name}「${String(raw).slice(0, 20)}」无效（应在 ${min} 到 ${max} 之间），已改用 ${def}`); return def; }
    if (n < soft) warnings.push(`${name} 只有 ${n}，单位是毫秒，这个值非常小`);
    return Math.round(n);
  };
  const systemTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
  let tz = $env.BRIEF_TZ || systemTz;
  try { new Intl.DateTimeFormat('en-CA', { timeZone: tz }); } catch (e) { warnings.push(`BRIEF_TZ「${String(tz).slice(0, 30)}」不是有效的时区，已改用系统时区 ${systemTz}`); tz = systemTz; }
  let view = String($env.BRIEF_VIEW || 'compact').toLowerCase();
  if (view !== 'compact' && view !== 'full') { warnings.push(`BRIEF_VIEW「${view.slice(0, 20)}」无效（应为 compact 或 full），已改用 compact`); view = 'compact'; }
  let baseDate = null;
  if ($env.BRIEF_BASE_DATE) {
    baseDate = normalizeDate($env.BRIEF_BASE_DATE) || null;
    if (!baseDate) warnings.push(`BRIEF_BASE_DATE「${String($env.BRIEF_BASE_DATE).slice(0, 20)}」不是有效日期，已忽略`);
    else if (new Date(`${baseDate}T00:00:00Z`).getUTCDay() !== 1) warnings.push(`BRIEF_BASE_DATE ${baseDate} 不是周一：它应该是第 1 周周一的日期，否则「第 N 周」会整体错位`);
  }
  const regex = (name, flags) => { const v = $env[name]; if (!v) return null; try { return new RegExp(v, flags); } catch (e) { warnings.push(`${name} 不是有效的正则表达式，已忽略`); return null; } };
  return {
    warnings, tz, view, baseDate,
    eventDays: num('BRIEF_EVENT_DAYS', 3, 1, 14),
    aiTimeoutMs: num('BRIEF_AI_TIMEOUT_MS', 90000, 1, 600000, 10000),
    ingestBudgetMs: num('BRIEF_INGEST_BUDGET_MS', 150000, 1, 500000, 20000),
    chunkChars: num('BRIEF_CHUNK_CHARS', 24000, 4000, 60000),
    autoConfirm: /^(1|true|yes)$/i.test(String($env.BRIEF_AUTO_CONFIRM || '')),
    ignore: regex('BRIEF_IGNORE', 'i'),
    strip: regex('BRIEF_STRIP', 'gi'),
    test: !!$env.BRIEF_TEST,
  };
}


const t0 = Date.now();
const cal = $('Read calendars').first().json;
const today = cal.today;
const S = loadSettings($env);
const inbox = $env.BRIEF_INBOX || path.join(os.homedir(), 'n8n-inbox');
const stateDir = $env.BRIEF_STATE_DIR || path.join($env.BRIEF_HOME || path.join(os.homedir(), '.n8n-morning-brief'), 'data', 'state');
const tasksFile = path.join(inbox, 'tasks.csv');
const seenFile = path.join(stateDir, 'processed.json');
const MAX_FILES = 10, MAX_CHUNKS = 10, MAX_ATTEMPTS = 3, MAX_LATE_RETRIES = 3, RANGE_DAYS = 366, MAX_EXTRACT_ATTEMPTS = 5;
const LATE_RETRY_MS = 20 * 3600 * 1000; // a bit under a day: a run that starts a few seconds earlier than yesterday's must still count as the next day
const MAX_CHARS = S.chunkChars;
// The whole run must finish well inside the Code-node timeout and the caller's execution budget:
// no new AI call is started after the budget, and one call may take at most aiTimeoutMs.
const BUDGET_MS = S.ingestBudgetMs;
const AI_TIMEOUT_MS = S.aiTimeoutMs;
