  return st.isFile();
});
const pending = [];
const present = new Set();
for (const n of names) {
  const ext = path.extname(n).toLowerCase();
  if (!SUPPORTED.includes(ext)) { if (!seen.done[`unsupported:${n}`]) { errors.push(`不支持的文件格式：${n}（支持 pdf、docx、txt、md）`); seen.done[`unsupported:${n}`] = today; } continue; }
  const hash = crypto.createHash('sha256').update(fs.readFileSync(path.join(inbox, n))).digest('hex');
  present.add(hash);
  if (seen.done[hash]) {
    stats.skipped++;
    // a long file that was only read in part is mentioned once a week for as long as it stays in the inbox
    const tr = seen.truncated[hash];
    if (tr && !seen.done[hash].ignored && daysBetween(tr.remindedAt || '1970-01-01', today) >= 7) { errors.push(`${n} 太长（超过 ${MAX_CHUNKS} 段），只读了前 ${MAX_CHUNKS * MAX_CHARS} 个字符，后面的没读：请拆分后再放入`); tr.remindedAt = today; }
    continue;
  }
  const fails = seen.failed[hash] || 0;
  if (fails >= MAX_ATTEMPTS) {
    // After three quick failures a file gets one more try per day (at most MAX_LATE_RETRIES): a provider that was down
    // recovers by itself, a hopeless file eventually stops costing money. Older state without a timestamp is eligible at once.
    if (fails - MAX_ATTEMPTS >= MAX_LATE_RETRIES) { if (!seen.gaveUp[hash]) { errors.push(`${n} 多次处理失败，已放弃：请检查文件内容，或运行 scripts/inbox-tool.mjs retry 重新处理`); seen.gaveUp[hash] = today; } stats.skipped++; continue; }
    if (Date.now() - (seen.failedAt[hash] || 0) < LATE_RETRY_MS) { stats.skipped++; continue; }
  }
  const ex = extractionState(ext, hash);
  if (ex.gaveUp !== undefined) { if (!seen.gaveUp[hash]) { errors.push(`${n} 无法提取文字（已尝试 ${MAX_EXTRACT_ATTEMPTS} 次）：${safe(ex.gaveUp)}。请移走它，或重新导出为可复制文字的 PDF/DOCX`); seen.gaveUp[hash] = today; } stats.skipped++; continue; }
  if (ex.waiting) { errors.push(`${n}：${safe(ex.waiting)}`); stats.skipped++; continue; }
  const reread = Object.entries(seen.done).some(([h, d]) => h !== hash && d && typeof d === 'object' && d.file === n && !d.ignored);
  pending.push({ n, hash, size: fs.statSync(path.join(inbox, n)).size, reread });
}
for (const h of Object.keys(seen.partial)) if (!present.has(h)) { delete seen.partial[h]; delete seen.offset[h]; delete seen.chunkEnd[h]; } // the file changed or was removed
for (const h of Object.keys(seen.truncated)) if (!present.has(h)) delete seen.truncated[h];
// Small files first, so one huge document can never starve the others.
pending.sort((a, b) => a.size - b.size);

let remaining = 0;
if (DRY && pending.length) {
  errors.push(`预览模式：${pending.length} 个新文件没有被处理（真实运行时才会调用 AI 并写入任务表）`);
  remaining = pending.length;
} else if (pending.length && !($env.AI_BASE_URL && $env.AI_MODEL)) {
  errors.push(`收件夹里有 ${pending.length} 个新文件，但还没配置 AI（运行 scripts/set-ai-key.sh）`);
} else if (pending.length) {
  let tasks = null;
  try { tasks = readTasks(tasksFile, fs); } catch (e) { errors.push(safe(e.message)); }
  if (tasks === null) {
    remaining = pending.length; // a damaged task table blocks ingestion: nothing is sent to the AI, nothing is rewritten
  } else {
    knownCourses = [...new Set(tasks.map((t) => t['分类']).filter(Boolean))].slice(0, 30);
    priorTasks = {};
    for (const p of pending) if (p.reread) priorTasks[p.n] = tasks.filter((t) => t['来源'] === p.n && statusKind(t['状态']) !== 'ignored');
    // "Assignment 1" and "Assignment 1 submission (Python)" are the same thing said twice: one contains the other, or
    // they share most of their words.
    const words = (s) => new Set(norm(s).replace(/[^\p{L}\p{N}]+/gu, ' ').split(' ').filter(Boolean));
    const similar = (a, b) => { const x = norm(a), y = norm(b); if (!x || !y) return false; if (x.includes(y) || y.includes(x)) return true; const wa = words(a), wb = words(b); let both = 0; for (const w of wa) if (wb.has(w)) both++; return both >= 2 && both * 2 >= Math.max(wa.size, wb.size); };
    // Same title + same due date is only a duplicate when the (normalised) course name is exactly the same too. Anything
    // less certain is KEPT and flagged in the note: a spare row can be ignored with one edit, a silently dropped task
    // is never noticed. (The AI does not always name a course the same way, so re-reading an edited file can flag rows.)
    const norm = (s) => String(s).toLowerCase().replace(/[\s_\-]+/g, '');
    const keyOf = (t, d) => `${norm(t)}|${d}`;
    const index = new Map();
    for (const t of tasks) { const k = keyOf(t['任务'], normalizeDate(t['截止日'])); index.set(k, [...(index.get(k) || []), t]); }

    const addTask = (raw, source) => {
      if (!raw || typeof raw !== 'object' || !clip(raw.title, 200)) return 0;
      const { due, note, certain } = resolveDue(raw);
      const category = clip(raw.category || path.basename(source, path.extname(source)), 80);
      const title = clip(raw.title, 200);
      const k = keyOf(title, due);
      const same = index.get(k) || [];
      if (same.some((r) => norm(r['分类']) === norm(category))) return 0;
      // a new version of the same file: a row that reads like one already taken from the old version is flagged, not doubled
      const older = !same.length && priorTasks[source] ? priorTasks[source].filter((r) => similar(r['任务'], title) && (norm(r['分类']) === norm(category) || !due || normalizeDate(r['截止日']) === due)) : [];
      const hours = Number(raw.hours);
      // BRIEF_AUTO_CONFIRM (off by default): tasks whose date is explicit and that are not possible duplicates go straight to 进行中.
      const status = S.autoConfirm && certain && !same.length && !older.length ? '进行中' : '待确认';
      const flag = same.length ? `可能与「${same[0]['来源']}」里的同名任务重复` : older.length ? `文件有新版本：可能是「${clip(older[0]['任务'], 60)}」的更新，旧的那条可改成「忽略」` : '';
      const row = { '状态': status, '分类': category, '任务': title, '截止日': due, '预估耗时': hours > 0 && hours <= 200 ? `${hours}h` : '', '来源': source, '添加时间': today, '备注': flag ? `${note ? `${note}；` : ''}${flag}` : note };
      tasks.push(row);
      index.set(k, [...same, row]);
      return 1;
    };

    let budgetHit = false;
    let handled = 0;
    let backedUp = false; // tasks.csv.bak is taken once per run: the file exactly as the user left it
    const persistTasks = () => { writeTasks(tasksFile, tasks, fs, { backup: !backedUp }); backedUp = true; };
    for (const { n, hash } of pending.slice(0, MAX_FILES)) {
      if (Date.now() - t0 > BUDGET_MS) { budgetHit = true; break; }
      let finished = false;
      try {
        const text = extractText(path.join(inbox, n), hash).trim();
        if (text.length < 20) throw new Error('文件里几乎没有可读文字（可能是扫描图片）');
        // Progress is recorded as the number of CHARACTERS already read, not as a chunk number, so changing the chunk size
        // between runs cannot skip or repeat any text. (Older state with only a chunk number is converted once.)
        let done = seen.partial[hash] || 0;
        let consumed = seen.offset[hash];
        // Older state recorded only a chunk NUMBER, and the chunk size it was read with is unknown (it may have changed):
        // guessing the position could skip text, so such a file is read again from the start. Tasks that are exactly the
        // same (course, title, date) are not added twice.
        if (consumed === undefined) { consumed = 0; done = 0; delete seen.chunkEnd[hash]; }
        // The document is read in logical chunks [start, end). A chunk that was only half read when time ran out is
        // FINISHED first (its end is stored), and only then is it counted, so resuming never resets the 10-chunk limit.
        const units = [];
        let pos = consumed;
        const openEnd = seen.chunkEnd[hash];
        if (openEnd > consumed && openEnd <= text.length) { units.push([consumed, openEnd]); pos = openEnd; }
        for (const c of chunks(text.slice(pos))) { units.push([pos, pos + c.length]); pos += c.length; }
        const use = units.slice(0, Math.max(0, MAX_CHUNKS - done)).map(([a, b]) => text.slice(a, b));
        const useEnds = units.slice(0, use.length).map(([, b]) => b);
        const parts = units;
        if (parts.length > use.length) {
          // Say it on the first day and then only once a week, so a long file is not nagged about every morning.
          const prev = seen.truncated[hash];
          const due = !prev || daysBetween(prev.remindedAt || '1970-01-01', today) >= 7;
          if (due) errors.push(`${n} 太长（超过 ${MAX_CHUNKS} 段），只读了前 ${MAX_CHUNKS * MAX_CHARS} 个字符，后面的没读：请拆分后再放入`);
          seen.truncated[hash] = { file: n, chunks: done + parts.length, read: MAX_CHUNKS, remindedAt: due ? today : prev.remindedAt };
        }
        const halves = (t) => { let cut = t.lastIndexOf('\n', Math.floor(t.length / 2)); if (cut < t.length * 0.25) cut = Math.floor(t.length / 2); return [t.slice(0, cut), t.slice(cut)]; };
        for (let i = 0; i < use.length && !budgetHit; i++) {
          // A chunk is read as one piece. A piece that is too slow is read as two halves instead (once). EVERY piece that
          // succeeds is saved at once, with the exact character position, so running out of time loses nothing.
          const pieces = [{ text: use[i], half: false }];
          seen.chunkEnd[hash] = useEnds[i]; // where this logical chunk ends, kept until it is complete
          while (pieces.length) {
            if (Date.now() - t0 > BUDGET_MS) { budgetHit = true; break; }
            let list;
            try { list = await askAI.call(this, n, pieces[0].text, done + i + 1, done + use.length, !pieces[0].half); } catch (e) {
              if (!e.tooSlow) throw e;
              pieces.splice(0, 1, ...halves(pieces[0].text).map((t) => ({ text: t, half: true })));
              continue;
            }
            let added = 0;
            for (const raw of list) added += addTask(raw, n);
            if (added) { persistTasks(); stats.newTasks += added; }
            consumed += pieces.shift().text.length;
            seen.offset[hash] = consumed; save();
          }
          if (!budgetHit) { seen.partial[hash] = done + i + 1; delete seen.chunkEnd[hash]; save(); }
        }
        finished = !budgetHit;
      } catch (e) {
        if ($env.BRIEF_DEBUG) console.error(e.stack);
        if (e.budget) budgetHit = true; // out of time, not a failure of the file: it continues tomorrow
        else if (e.gaveUp) {
          if (!seen.gaveUp[hash]) { errors.push(`${n} 无法提取文字（已尝试 ${MAX_EXTRACT_ATTEMPTS} 次）：${safe(e.message)}。请移走它，或重新导出为可复制文字的 PDF/DOCX`); seen.gaveUp[hash] = today; }
          handled++; // permanent: do not count it as "continue tomorrow"
        } else if (e.waiting) errors.push(`${n}：${safe(e.message)}`);
        else {
          seen.failed[hash] = (seen.failed[hash] || 0) + 1;
          seen.failedAt[hash] = Date.now();
          errors.push(`文件处理失败：${n}（${safe(e.message)}）${seen.failed[hash] >= MAX_ATTEMPTS ? '，暂停重试，之后每天最多再试一次' : ''}`);
          handled++;
        }
      }
      if (finished) { seen.done[hash] = { file: n, at: today }; delete seen.partial[hash]; delete seen.offset[hash]; delete seen.chunkEnd[hash]; delete seen.failed[hash]; delete seen.failedAt[hash]; stats.files++; handled++; }
      save();
    }
    remaining = pending.length - handled;
    if (remaining > 0) errors.push(`还有 ${remaining} 个文件明天继续处理${budgetHit ? '（本次时间预算已用完）' : ''}`);
  }
}
save();
return [{ json: { ...cal, ingest: { ...stats, errors, remaining, metrics: { ...metrics, totalMs: Date.now() - t0 } }, tasksFile, inbox } }];

// n8n Code node ("Run Once for All Items"). Turns tasks + calendar events into a Discord embed payload.
const fs = require('fs');
// Shared by several Code nodes (inlined by the build script via the include marker).
const TASK_COLUMNS = ['状态', '分类', '任务', '截止日', '预估耗时', '来源', '添加时间', '备注'];
const REQUIRED_COLUMNS = ['状态', '任务', '截止日'];
const TEXT_COLUMNS = ['分类', '任务', '备注', '来源'];

// What the "状态" column means. Anything unknown is treated as active-but-suspicious by the callers, never silently hidden.
function statusKind(s) {
  const v = String(s ?? '').trim().toLowerCase();
  if (v === '进行中' || v === 'active' || v === 'doing') return 'active';
  if (v === '待确认' || v === 'pending') return 'pending';
  if (['完成', '已完成', 'done', 'completed', 'finished'].includes(v)) return 'done';
  if (['忽略', '已忽略', 'ignore', 'ignored', '取消', '已取消', 'cancelled', 'canceled'].includes(v)) return 'ignored';
  return v === '' ? 'pending' : 'unknown';
}

function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', q = false;
  const s = String(text).replace(/^\uFEFF/, '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === '"' && s[i + 1] === '"') { cell += '"'; i++; }
      else if (c === '"') q = false;
      else cell += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some((x) => x !== '')) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((x) => x !== '')) rows.push(row);
  return rows;
}

// Accepts what people and spreadsheets write: 2026-10-02, 2026/10/2, 2026.10.2 (optionally followed by a time).
// Returns YYYY-MM-DD, or '' when it is not a real calendar date.
function normalizeDate(s) {
  const str = String(s ?? '').trim();
  let m = str.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T].*)?$/);
  if (!m) {
    // Excel saves 25/12/2026 (D/M, Hong Kong, UK) or 12/25/2026 (M/D, US). Only the unambiguous ones are accepted:
    // 3/4/2026 could be either, and a wrong guess is worse than the "unrecognised date" note the brief gives.
    const dm = str.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})(?:[ T].*)?$/);
    if (!dm) return '';
    const a = Number(dm[1]), b = Number(dm[2]);
    if (a > 12 && b <= 12) m = [str, dm[3], dm[2], dm[1]]; else if (b > 12 && a <= 12) m = [str, dm[3], dm[1], dm[2]]; else return '';
  }
  const iso = `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  const d = new Date(`${iso}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== iso ? '' : iso;
}

// Spreadsheet formula injection: text starting with = + - @ gets an apostrophe on write, removed again on read.
const neutralize = (v) => (/^[=+\-@\t\r]/.test(v) ? `'${v}` : v);
const restore = (v) => (/^'[=+\-@\t\r]/.test(v) ? v.slice(1) : v);

// Throws when the header is not recognisable: callers must then leave the file alone instead of rewriting it.
function readTasks(file, fs) {
  const withColumns = (arr, cols) => { arr.columns = cols; return arr; }; // the column list travels with the rows, so a header-only file keeps its custom columns
  if (!fs.existsSync(file)) return withColumns([], [...TASK_COLUMNS]);
  const rows = parseCsv(fs.readFileSync(file, 'utf8'));
  if (!rows.length) return withColumns([], [...TASK_COLUMNS]);
  const head = rows[0].map((h) => h.trim());
  const missing = REQUIRED_COLUMNS.filter((c) => !head.includes(c));
  if (missing.length) throw new Error(`任务表表头无法识别（缺少列：${missing.join('、')}），程序不会改动这个文件。请恢复表头：${TASK_COLUMNS.join(',')}`);
  // Columns the user added themselves (for example "优先级") are carried along and written back untouched.
  const extra = head.filter((h, i) => h && !TASK_COLUMNS.includes(h) && head.indexOf(h) === i);
  return withColumns(rows.slice(1).map((r) => Object.fromEntries([...TASK_COLUMNS, ...extra].map((c) => {
    const v = (r[head.indexOf(c)] ?? '').trim();
    return [c, TEXT_COLUMNS.includes(c) ? restore(v) : v];
  }))), [...TASK_COLUMNS, ...extra]);
}

// options.backup (default true): keep the previous file as file.bak. A run that writes several times passes false after
// the first write, so the backup is always the file exactly as the user left it before the run.
function writeTasks(file, tasks, fs, options = {}) {
  const esc = (v) => (/[",\n\r]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
  const cell = (t, c) => esc(TEXT_COLUMNS.includes(c) ? neutralize(String(t[c] ?? '')) : String(t[c] ?? ''));
  const extra = [];
  for (const c of tasks.columns || []) if (!TASK_COLUMNS.includes(c) && !extra.includes(c)) extra.push(c);
  for (const t of tasks) for (const k of Object.keys(t)) if (!TASK_COLUMNS.includes(k) && !extra.includes(k)) extra.push(k);
  const cols = [...TASK_COLUMNS, ...extra];
  const lines = [cols.map(esc).join(','), ...tasks.map((t) => cols.map((c) => cell(t, c)).join(','))];
  if (options.backup !== false && fs.existsSync(file)) fs.copyFileSync(file, `${file}.bak`);
  const tmp = `${file}.tmp`;
  fs.writeFileSync(tmp, `\uFEFF${lines.join('\r\n')}\r\n`, 'utf8'); // BOM so Excel shows Chinese correctly
  fs.renameSync(tmp, file);
}

// Validated settings, shared by the Code nodes (inlined by the build script). Needs csv.js (normalizeDate) before it.
// A wrong value never stops the brief: it falls back to a safe default and the fallback is listed in `warnings`,
// which the brief prints, so a typo costs you a warning line instead of the whole morning.
function loadSettings($env) {
  const warnings = [];
  // soft: values below it are accepted but flagged (a budget of "5" is almost certainly meant as seconds, not milliseconds)
  const num = (name, def, min, max, soft = min) => {
    const raw = $env[name];
    if (raw === undefined || raw === '') return def;
    const n = Number(raw);
    if (!Number.isFinite(n) || n < min || n > max) { warnings.push(`${name}「${String(raw).slice(0, 20)}」无效（应在 ${min} 到 ${max} 之间），已改用 ${def}`); return def; }
    if (n < soft) warnings.push(`${name} 只有 ${n}，单位是毫秒，这个值非常小`);
    return Math.round(n);
  };
  const systemTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
  let tz = $env.BRIEF_TZ || systemTz;
  try { new Intl.DateTimeFormat('en-CA', { timeZone: tz }); } catch (e) { warnings.push(`BRIEF_TZ「${String(tz).slice(0, 30)}」不是有效的时区，已改用系统时区 ${systemTz}`); tz = systemTz; }
  let view = String($env.BRIEF_VIEW || 'compact').toLowerCase();
  if (view !== 'compact' && view !== 'full') { warnings.push(`BRIEF_VIEW「${view.slice(0, 20)}」无效（应为 compact 或 full），已改用 compact`); view = 'compact'; }
  let baseDate = null;
  if ($env.BRIEF_BASE_DATE) {
    baseDate = normalizeDate($env.BRIEF_BASE_DATE) || null;
    if (!baseDate) warnings.push(`BRIEF_BASE_DATE「${String($env.BRIEF_BASE_DATE).slice(0, 20)}」不是有效日期，已忽略`);
    else if (new Date(`${baseDate}T00:00:00Z`).getUTCDay() !== 1) warnings.push(`BRIEF_BASE_DATE ${baseDate} 不是周一：它应该是第 1 周周一的日期，否则「第 N 周」会整体错位`);
  }
  const regex = (name, flags) => { const v = $env[name]; if (!v) return null; try { return new RegExp(v, flags); } catch (e) { warnings.push(`${name} 不是有效的正则表达式，已忽略`); return null; } };
  return {
    warnings, tz, view, baseDate,
    eventDays: num('BRIEF_EVENT_DAYS', 3, 1, 14),
    aiTimeoutMs: num('BRIEF_AI_TIMEOUT_MS', 90000, 1, 600000, 10000),
    ingestBudgetMs: num('BRIEF_INGEST_BUDGET_MS', 150000, 1, 500000, 20000),
    chunkChars: num('BRIEF_CHUNK_CHARS', 24000, 4000, 60000),
    autoConfirm: /^(1|true|yes)$/i.test(String($env.BRIEF_AUTO_CONFIRM || '')),
    ignore: regex('BRIEF_IGNORE', 'i'),
    strip: regex('BRIEF_STRIP', 'gi'),
    test: !!$env.BRIEF_TEST,
  };
}

const input = $input.first().json;
const { today, days, calendars } = input;
const S = loadSettings($env);
const ingest = input.ingest || { newTasks: 0, errors: [] };
const scrub = (m) => String(m).replace(/https?:\/\/\S+/g, '<链接>'); // links can be secrets
const errors = [...(input.errors || []), ...(ingest.errors || [])].map(scrub);
const warnings = [...new Set([...(input.warnings || []), ...S.warnings])].map(scrub);
const missed = ((() => { try { return $('Webhook').first().json.body.missed; } catch (e) { return []; } })() || []).filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));

// Text from documents and shared calendars is untrusted: stop Discord from rendering it as markdown or links.
const oneLine = (s) => String(s).replace(/[\r\n\t]+/g, ' ').trim(); // a line break in a title would start a new markdown line (for example a heading)
const esc = (s) => String(s).replace(/([\\*_~|>`\[\]()])/g, '\\$1');
const clean = (s) => (S.strip ? String(s).replace(S.strip, '').replace(/\s{2,}/g, ' ').trim() : String(s));
const events = (input.events || []).filter((e) => !(S.ignore && S.ignore.test(e.title))).map((e) => ({ ...e, title: esc(oneLine(clean(e.title)) || '(无标题)'), location: e.location ? esc(oneLine(e.location)) : '' }));

const weekday = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString('zh-CN', { weekday: 'short', timeZone: 'UTC' });
const shift = (d, n) => { const t = new Date(`${d}T12:00:00Z`); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
const daysBetween = (a, b) => Math.round((new Date(`${b}T00:00:00Z`) - new Date(`${a}T00:00:00Z`)) / 86400000);
const short = (d) => `${d.slice(5)} ${weekday(d)}`;

// ---- tasks (status is edited by hand in tasks.csv) ----
let tasks = [];
let tableError = false;
try { if (input.tasksFile) tasks = readTasks(input.tasksFile, fs); } catch (e) { tableError = true; errors.push(`任务表读取失败：${scrub(e.message).slice(0, 200)}`); }
// A cell edited in Excel can hold a line break (Alt-Enter): in a title it would end the task line and could start a markdown
// heading or list on the next one. Every text that is printed is made one line here, once, for both views.
tasks = tasks.map((t) => ({ ...t, '任务': oneLine(t['任务'] || ''), '分类': oneLine(t['分类'] || ''), '预估耗时': oneLine(t['预估耗时'] || '') }));
const kind = (t) => statusKind(t['状态']);
const active = tasks.filter((t) => kind(t) === 'active');
const pendingTasks = tasks.filter((t) => kind(t) === 'pending');
const unknownStatus = tasks.filter((t) => kind(t) === 'unknown').length;
const dueOf = (t) => normalizeDate(t['截止日']); // accepts 2026-10-02, 2026/10/2 (what Excel writes back) and 2026.10.2
const withDue = active.filter((t) => dueOf(t)).map((t) => ({ t, due: dueOf(t), left: daysBetween(today, dueOf(t)) })).sort((a, b) => a.left - b.left);
const noDue = active.length - withDue.length;
const unreadable = active.filter((t) => t['截止日'] && !dueOf(t)).length;
const noDueNote = noDue ? `📌 ${noDue} 项进行中的任务没有可用的截止日${unreadable ? `（其中 ${unreadable} 项填了日期但无法识别）` : ''}` : '';
const dot = (left) => (left < 0 ? '🔴' : left <= 3 ? '🟠' : left <= 7 ? '🟡' : '🟢');
const taskLine = ({ t, due, left }) => {
  const when = left < 0 ? `逾期 ${-left} 天` : left === 0 ? '今天截止' : `${short(due)} · 还剩 ${left} 天`;
  return `${dot(left)} **${esc(t['任务'])}** · ${when}${t['预估耗时'] ? ` · 约 ${esc(t['预估耗时'])}` : ''}${t['分类'] ? ` · _${esc(t['分类'])}_` : ''}`;
};
// Old tasks nobody marked as done must not push tomorrow's deadline off the page: overdue items are capped (the most
// recent ones, which can still be saved, come first) and the rest is summarised with a hint how to clean them up.
const MAX_OVERDUE = 3;
const overdueAll = withDue.filter((x) => x.left < 0).sort((a, b) => b.left - a.left); // most recently overdue first
const overdueShown = overdueAll.slice(0, MAX_OVERDUE);
const overdueHidden = overdueAll.slice(MAX_OVERDUE);
const dueToday = withDue.filter((x) => x.left === 0);
const dueWeek = withDue.filter((x) => x.left > 0 && x.left <= 7);
const dueLater = withDue.filter((x) => x.left > 7 && x.left <= 30);
const overdueNote = overdueHidden.length ? `🧹 另有 ${overdueHidden.length} 项逾期更久（最久 ${-overdueHidden[overdueHidden.length - 1].left} 天）：做完的请在 tasks.csv 里改成「完成」，不要的改成「忽略」` : '';

// ---- calendar ----
const failedCals = Number(input.failed || 0);
const cachedAges = input.cached || [];
const calendarUnknown = calendars > 0 && failedCals >= calendars && events.length === 0; // every calendar failed: "no events" would be a lie
// On day d, a timed event that began on an earlier day (a night shift, a trip) is a continuation: it is shown with the time
// it ends that day, never again with its start time as if it began then.
const cont = (e, d) => !e.allDay && d && e.day < d;
const span = (e, d) => (cont(e, d) ? (e.endDay === d ? `\`续 至 ${e.endHM}\`` : '`续 · 全天`')
  : e.endDay && e.endDay !== e.day ? `\`${e.startHM} → ${e.endDay.slice(5)} ${e.endHM}\`` : `\`${e.startHM}–${e.endHM}\``);
const evLine = (e, d) => `${e.allDay ? '`  全天  `' : span(e, d)} ${e.title}${e.location ? ` · ${e.location}` : ''}`;
const onDay = (d) => events.filter((e) => (e.allDay ? e.startDay <= d && d < e.endDay : e.day <= d && d <= (e.endDay || e.day)));
const todayEvents = onDay(today);
const cachedNote = cachedAges.length ? `ℹ️ 有 ${cachedAges.length} 个日历没连上，日程来自 ${Math.max(...cachedAges)} 小时前的缓存` : '';

const bodyTest = (() => { try { return $('Webhook').first().json.body.test === true; } catch (e) { return false; } })(); // a single-run mode travels in the request, so it also works on a reused n8n whose environment we cannot change
const titlePrefix = (S.test || bodyTest) ? '🧪 测试 · ' : '';
// Shorten a (markdown-escaped) text to n characters, marking it with … and never leaving half an escape at the end, nor a
// bracket opened and never closed ("阅读笔记（两页…" reads badly): it ends before that bracket when enough is left,
// otherwise the bracket is closed after the ….
const OPENERS = '（(《「『【[“'; const CLOSERS = '）)》」』】]”';
const cutText = (x, n) => {
  const t = String(x); if (t.length <= n) return t;
  let c = t.slice(0, n - 1).replace(/\\+$/, '');
  let depth = 0; let open = -1;
  for (let i = c.length - 1; i >= 0; i--) {
    if (CLOSERS.includes(c[i])) depth++;
    else if (OPENERS.includes(c[i])) { if (depth) depth--; else { open = i; break; } }
  }
  if (open < 0) return `${c}…`;
  if (open >= n / 2) return `${c.slice(0, open).replace(/\\+$/, '')}…`;
  const closer = CLOSERS[OPENERS.indexOf(c[open])]; // opened early: keep the text and close the bracket after the …
  return `${c}…${')]'.includes(closer) ? '\\' : ''}${closer}`;
};
const notes = () => {
  const n = [];
  if (noDueNote) n.push(noDueNote);
  if (overdueNote) n.push(overdueNote);
  if (pendingTasks.length) {
    const list = pendingTasks.slice(0, 3).map((t) => `　• ${cutText(esc(t['任务']), 60)}${dueOf(t) ? `（${dueOf(t).slice(5)}）` : '（无日期）'}`);
    n.push(`🆕 ${pendingTasks.length} 条任务待确认（在控制台的「任务」页确认，或编辑收件夹里的 tasks.csv）\n${list.join('\n')}${pendingTasks.length > 3 ? `\n　…还有 ${pendingTasks.length - 3} 条` : ''}\n　把「待确认」改成「进行中」；不要的改成「忽略」`);
  }
  if (unknownStatus) n.push(`❓ ${unknownStatus} 项任务的状态看不懂（应为 待确认 / 进行中 / 完成 / 忽略）`);
  if (cachedNote) n.push(cachedNote);
  if (missed.length) n.push(`ℹ️ ${missed.map((d) => d.slice(5)).join('、')} 漏发，今天补上`);
  if ($env.BRIEF_NOTE) n.push(cutText(`ℹ️ ${esc(oneLine(scrub($env.BRIEF_NOTE)))}`, 240)); // e.g. "sent by the direct engine because n8n was unavailable"
  if (!calendars) n.push('ℹ️ 未配置日历');
  if (warnings.length) n.push(cutText(`⚙️ 设置提示：${warnings.join('；')}`, 500));
  // Problems are always reported, but summarised: the first three (shortened) and how many more there are.
  if (errors.length) n.push(`⚠️ ${errors.length > 1 ? `${errors.length} 个问题：` : ''}${errors.slice(0, 3).map((e) => cutText(e, 160)).join('；')}${errors.length > 3 ? `；另有 ${errors.length - 3} 个，详见运行日志` : ''}`);
  return n;
};

// ---- compact view (default): one card, one line per task, one summary line for the schedule ----
const buildCompact = () => {
  // The card has room for 3900 characters (Discord allows 4096). Everything competes for it: tasks, the schedule and the
  // notes. Notes (problems, cached data, pending tasks) are never dropped; long titles and places are shortened (…);
  // when it still does not fit, events and then tasks are left out from the end, each list saying exactly how many are
  // not shown. Only as a very last resort is the text cut, at a line end where possible.
  const LIMIT = 3900;
  const urgent = [...overdueShown, ...dueToday, ...dueWeek];
  // the course / project goes after the date: "Assignment 1" means little when you take four courses
  const cat = (t) => (oneLine(t['分类'] || '') ? ` · _${cutText(esc(oneLine(t['分类'])), 16)}_` : '');
  const taskLine = ({ t, due, left }) => `${dot(left)} **${cutText(esc(t['任务']), 80)}** · ${left < 0 ? `逾期 ${-left} 天` : left === 0 ? '今天' : left <= 6 ? weekday(due) : due.slice(5)}${cat(t)}`;
  const evShort = (d) => (e) => `${e.allDay ? '`  全天  `' : span(e, d)} ${cutText(e.title, 70)}${e.location ? ` · ${cutText(e.location, 40)}` : ''}`;
  const n = notes().map((x) => cutText(x, 600));
  const tomorrow = shift(today, 1);
  const tmr = onDay(tomorrow);
  const laterDays = [];
  for (let i = 2; i <= days; i++) { const d = shift(today, i); const evs = onDay(d); if (evs.length) laterDays.push([d, evs]); }
  const render = (maxTasks, maxToday, maxTmr, maxLater) => {
    const out = urgent.slice(0, maxTasks).map(taskLine);
    if (urgent.length > maxTasks) out.push(`…还有 ${urgent.length - maxTasks} 项`);
    if (!urgent.length) out.push(tableError ? '❓ 任务表读取失败，今天的任务清单不完整（原因见下）' : '✅ 没有近期要交的任务');
    // tasks due later (8-30 days) are not left out silently: one line with the nearest three and how many there are
    if (dueLater.length) out.push(`🟢 再往后 30 天内还有 ${dueLater.length} 项：${dueLater.slice(0, 3).map(({ t, due }) => `${cutText(esc(t['任务']), 24)}（${due.slice(5)}${oneLine(t['分类'] || '') ? ` · ${cutText(esc(oneLine(t['分类'])), 12)}` : ''}）`).join('、')}${dueLater.length > 3 ? ' 等' : ''}`);
    if (calendarUnknown) out.push('', '❓ 日历读取失败，今天的日程未知');
    else if (calendars) {
      out.push('', todayEvents.length ? `🗓 **今天 ${todayEvents.length} 项日程**` : '🗓 今天没有日程');
      out.push(...todayEvents.slice(0, maxToday).map(evShort(today)));
      if (todayEvents.length > maxToday) out.push(`…还有 ${todayEvents.length - maxToday} 项`);
      if (tmr.length) {
        out.push('', `🔜 **明天 ${weekday(tomorrow)} · ${tmr.length} 项**`, ...tmr.slice(0, maxTmr).map(evShort(tomorrow)));
        if (tmr.length > maxTmr) out.push(`…还有 ${tmr.length - maxTmr} 项`);
      }
      const shown = laterDays.slice(0, maxLater).map(([d, evs]) => `　${short(d)}：${evs.slice(0, 3).map((e) => `${e.allDay ? '' : cont(e, d) ? (e.endDay === d ? `续至${e.endHM} ` : '续 ') : `${e.startHM} `}${cutText(e.title, 30)}`).join('、')}${evs.length > 3 ? ` 等 ${evs.length} 项` : ''}`);
      if (shown.length) out.push('', '📆 之后几天', ...shown);
      if (laterDays.length > maxLater) out.push(`　…还有 ${laterDays.length - maxLater} 天有日程`);
    }
    if (n.length) out.push('', ...n);
    return out.join('\n');
  };
  let mk = 9, mt = 20, mm = 8, ml = laterDays.length;
  let description = render(mk, mt, mm, ml);
  while (description.length > LIMIT && (ml > 0 || mm > 0 || mt > 0 || mk > 0)) {
    if (ml > 0) ml--; else if (mm > 0) mm--; else if (mt > 0) mt--; else mk--;
    description = render(mk, mt, mm, ml);
  }
  if (description.length > LIMIT) { // notes alone are too long (should not happen): cut, at a line end if there is one
    const at = description.lastIndexOf('\n', LIMIT - 2);
    description = at > LIMIT / 2 ? `${description.slice(0, at)}\n…` : cutText(description, LIMIT);
  }
  return [{ title: `${titlePrefix}${+today.slice(5, 7)}月${+today.slice(8)}日 ${weekday(today)}`, description, color: overdueAll.length ? 0xe74c3c : urgent.some((x) => x.left <= 3) ? 0xe67e22 : urgent.length ? 0xf1c40f : 0x2ecc71 }];
};

// ---- full view (BRIEF_VIEW=full): grouped fields, upcoming days, later tasks, footer ----
const buildFull = () => {
  // ---- embed helpers (Discord limits: field value 1024, description 4096, total 6000) ----
  const fit = (lines, max = 1000) => {
    const out = [];
    let len = 0;
    for (let i = 0; i < lines.length; i++) {
      if (len + lines[i].length + 1 > max - 24) { out.push(`…还有 ${lines.length - i} 项`); break; }
      out.push(lines[i]); len += lines[i].length + 1;
    }
    return out.join('\n');
  };
  const fields = [];
  const add = (name, lines) => { if (lines.length) fields.push({ name, value: fit(lines), inline: false }); };
  const nowList = [...overdueShown, ...dueToday];
  add(`🔥 今天必做（${nowList.length}）`, nowList.map(taskLine));
  if (!nowList.length) fields.push({ name: '🔥 今天必做', value: tableError ? '❓ 任务表读取失败，清单不完整' : '没有到期的任务 ✅', inline: false });
  if (calendarUnknown) fields.push({ name: '🗓 今日日程', value: '❓ 日历读取失败，今天的日程未知', inline: false });
  else {
    add(`🗓 今日日程（${todayEvents.length}）`, todayEvents.map((e) => evLine(e, today)));
    if (!todayEvents.length) fields.push({ name: '🗓 今日日程', value: '今天没有日程 🎉', inline: false });
  }
  add(`⚠️ 本周要紧（${dueWeek.length}）`, dueWeek.map(taskLine));

  const upcoming = [];
  for (let i = 1; i <= days; i++) {
    const d = shift(today, i);
    const evs = onDay(d);
    if (!evs.length) continue;
    if (evs.length <= 3) { upcoming.push(`**${short(d)}**\n${evs.map((e) => evLine(e, d)).join('\n')}`); continue; }
    const timed = evs.filter((e) => !e.allDay);
    const range = timed.length ? ` · \`${timed[0].startHM}–${timed[timed.length - 1].endHM}\`` : '';
    const allDay = evs.filter((e) => e.allDay).map((e) => e.title);
    upcoming.push(`**${short(d)}** · ${evs.length} 项${range}${allDay.length ? `\n　全天：${allDay.join('、')}` : ''}`);
  }
  if (!calendarUnknown) add(`🔜 接下来 ${days} 天`, upcoming);
  add(`🗂 更远的（30 天内 ${dueLater.length} 项）`, dueLater.slice(0, 5).map(taskLine).concat(dueLater.length > 5 ? [`…还有 ${dueLater.length - 5} 项`] : []));

  const color = overdueAll.length ? 0xe74c3c : dueToday.length ? 0xe67e22 : dueWeek.length ? 0xf1c40f : 0x2ecc71;
  const summary = [
    nowList.length ? `🔥 **${nowList.length}** 项必做` : '',
    dueWeek.length ? `⚠️ **${dueWeek.length}** 项本周要紧` : '',
    todayEvents.length ? `🗓 **${todayEvents.length}** 项日程` : '',
  ].filter(Boolean).join('　·　') || '今天很清爽 ✨';
  const tm = input.timing || {};
  const im = ingest.metrics || {};
  const embeds = [{
    title: `${titlePrefix}📅 ${+today.slice(5, 7)}月${+today.slice(8)}日 ${weekday(today)} · 早安`,
    description: summary,
    color,
    fields,
    footer: { text: `${tasks.length ? `任务表 ${active.length} 项进行中` : '还没有任务'} · ${calendars} 个日历 · 读日历 ${Math.round((tm.totalMs || 0) / 100) / 10}s · 入库 ${Math.round((im.totalMs || 0) / 100) / 10}s${im.aiCalls ? `（AI ${im.aiCalls} 次）` : ''}` },
    timestamp: new Date().toISOString(),
  }];
  const n = notes();
  if (n.length) embeds.push({ description: n.join('\n').slice(0, 3800), color: 0x95a5a6 });
  return embeds;
};
const embeds = S.view === 'full' ? buildFull() : buildCompact();

// Keep the whole payload under Discord's 6000-character embed budget by dropping the least important fields.
const size = () => embeds.reduce((n, e) => n + (e.title || '').length + (e.description || '').length + (e.footer?.text || '').length + (e.fields || []).reduce((m, f) => m + f.name.length + f.value.length, 0), 0);
while (size() > 5800 && (embeds[0].fields || []).length > 2) embeds[0].fields.pop();

const payload = { embeds, allowed_mentions: { parse: [] } }; // never let task titles ping @everyone
const message = embeds.map((e) => [e.title, e.description, ...(e.fields || []).map((f) => `【${f.name}】\n${f.value}`)].filter(Boolean).join('\n\n')).join('\n\n');
return [{ json: { payload, message, eventCount: events.length, taskCount: active.length, newTasks: ingest.newTasks, errorCount: errors.length, timing: { calendarMs: (input.timing || {}).totalMs || 0, ingestMs: (ingest.metrics || {}).totalMs || 0, aiCalls: (ingest.metrics || {}).aiCalls || 0 } } }];

// n8n Code node "Send to Discord" (the direct engine runs this same file). Posts the brief and says what happened in
// one of three words, which run-brief.sh turns into its delivery records:
//   sent      Discord stored the message (it returned the message id)
//   not_sent  nothing can have been delivered: no webhook, Discord refused it (4xx/429), or the connection never opened
//   unknown   the request may have reached Discord but no clear answer came back (timeout, broken connection, 5xx, no id)
// It never throws, so a failure of the workflow itself (HTTP 500) can only come from a step BEFORE this one, or from the
// attempt record below. A request that may already have been delivered is never repeated: only a refusal (429) or a
// connection that never opened is retried.
const fs = require('fs');
const path = require('path');
const os = require('os');

const brief = $input.first().json;
const body = (() => { try { return $('Webhook').first().json.body || {}; } catch (e) { return {}; } })();
const run = String(body.run || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 40);
const stateDir = $env.BRIEF_STATE_DIR || path.join($env.BRIEF_HOME || path.join(os.homedir(), '.n8n-morning-brief'), 'data', 'state');
const sleep = (ms) => (typeof setTimeout === 'function' ? new Promise((r) => setTimeout(r, ms)) : Promise.resolve());
const safe = (m) => String(m || '').replace(/https?:\/\/\S+/g, '<链接>').slice(0, 160);
const attemptFile = run ? path.join(stateDir, `attempt-${run}`) : '';
// A clear "not sent" removes the attempt record again: the record means "this may have reached Discord", which is now
// known to be false, so the caller can safely try again later (whichever engine ran this).
const out = (status, extra = {}) => {
  if (status === 'not_sent' && attemptFile) { try { fs.rmSync(attemptFile, { force: true }); } catch (e) { /* the record stays: treated as unknown */ } }
  return [{ json: { ...brief, send: { status, ...extra } } }];
};
// (Errors can lose their properties on the way out of n8n's task runner, so the message is read as a fallback.)
const httpCode = (e) => Number((e && (e.httpCode ?? e.statusCode ?? (e.response && (e.response.status ?? e.response.statusCode)))) || 0)
  || Number((String((e && e.message) || '').match(/status code (\d{3})|^(\d{3}) /) || []).slice(1).find(Boolean) || 0);
const errCode = (e) => String((e && (e.code || (e.cause && e.cause.code))) || (String((e && e.message) || '').match(/\b(ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ENETUNREACH|EHOSTUNREACH)\b/) || [])[1] || '');
const NEVER_SENT = /^(ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ENETUNREACH|EHOSTUNREACH)$/;
const retryAfter = (e) => { const h = (e && e.response && e.response.headers) || {}; const v = Number(e && e.retryAfter) || Number(h['retry-after']) || 0; return Number.isFinite(v) && v > 0 ? v : 0; };

const base = $env.DISCORD_WEBHOOK_URL;
if (!base) return out('not_sent', { reason: 'DISCORD_WEBHOOK_URL is not configured' });
// The attempt is recorded BEFORE anything can reach Discord. If this run dies later in any way (crash, kill, a failing
// step after this one), run-brief.sh finds this file and treats the day as "unknown" instead of sending again.
if (run) {
  try { fs.mkdirSync(stateDir, { recursive: true }); fs.writeFileSync(attemptFile, `${Date.now()}\n`); } catch (e) {
    return out('not_sent', { reason: `could not record the delivery attempt (${safe(e.message)})` });
  }
}
const url = `${base}${base.includes('?') ? '&' : '?'}wait=true`;
for (let attempt = 0; ; attempt++) {
  try {
    const res = await this.helpers.httpRequest({ method: 'POST', url, body: brief.payload, json: true, timeout: 30000 });
    if (res && res.id) return out('sent', { id: String(res.id) });
    return out('unknown', { reason: 'Discord answered without a message id' });
  } catch (e) {
    const code = httpCode(e);
    const neverSent = NEVER_SENT.test(errCode(e));
    // 502/503 (Cloudflare "bad gateway" / "service unavailable", frequent for a few seconds at a time) means the request
    // was not taken: without a retry the whole day's automation stops on it. 500 and 504 may have been processed: unknown.
    const notTaken = code === 502 || code === 503;
    if (attempt < 2 && (code === 429 || neverSent || notTaken)) { await sleep(Math.max(retryAfter(e) * 1000, 3000) * (notTaken ? attempt + 1 : 1)); continue; }
    if (code === 429 || (code >= 400 && code < 500) || neverSent) return out('not_sent', { reason: `Discord: ${code || errCode(e)} ${safe(e.message)}` });
    return out('unknown', { reason: `Discord: ${code || errCode(e) || 'no answer'} ${safe(e.message)}` });
  }
}

const s = $('Send to Discord').first().json;
const r = s.send || {};
const t = s.timing || {};
return [{ json: { status: r.status || 'unknown', reason: r.reason || '', events: s.eventCount, errors: s.errorCount, tasks: s.taskCount, newTasks: s.newTasks, aiCalls: t.aiCalls || 0, calendarMs: t.calendarMs || 0, ingestMs: t.ingestMs || 0, build: '96b1a70795ef' } }];
